        JobRole("financeHead", "manager", "ఫైనాన్స్ హెడ్", "Finance Head"),
        JobRole("accountant", "manager", "అకౌంటెంట్", "Accountant"),
        JobRole("salesManager", "manager", "సేల్స్ మేనేజర్", "Sales Manager"),
        JobRole("salesExecutive", "manager", "సేల్స్ ఎగ్జిక్యూటివ్", "Sales Executive"),
