        JobRole("eventManager", "manager", "ఈవెంట్ మేనేజర్", "Event Manager"),
        JobRole("hrManager", "manager", "HR మేనేజర్", "HR Manager"),
        JobRole("logisticsManager", "manager", "లాజిస్టిక్స్ మేనేజర్", "Logistics Manager"),
        JobRole("worker", "staff", "సిబ్బంది", "Worker / Staff"),
        JobRole("driver", "staff", "డ్రైవర్", "Driver"),
        JobRole("marketing", "manager", "మార్కెటింగ్ / CRM", "Marketing / CRM"),
        JobRole("systemAdmin", "manager", "సిస్టమ్ అడ్మిన్", "System Admin"),
        JobRole("auditor", "staff", "ఆడిటర్ / చూసేవారు", "Auditor / Viewer"),
