    /** Modules each manager-level role may open (the View column of the permission matrix). */
    private val MODULES: Map<String, Set<String>> = mapOf(
        "coo" to setOf("leads", "customers", "quotations", "bookings", "events", "vendors", "purchaseRequests", "purchaseOrders", "goodsReceipts", "expenses", "inventory", "recipes", "production", "staff", "attendance", "vehicles", "equipment", "reports"),
        "financeHead" to setOf("customers", "bookings", "invoices", "receipts", "vendors", "purchaseOrders", "goodsReceipts", "vendorBills", "expenses", "vendorPayments", "payroll", "ledger", "reports", "audit"),
        "accountant" to setOf("customers", "bookings", "invoices", "receipts", "vendors", "purchaseOrders", "goodsReceipts", "vendorBills", "expenses", "vendorPayments", "ledger", "reports"),
        "salesManager" to setOf("leads", "customers", "quotations", "bookings", "events", "invoices", "receipts", "marketing", "reports"),
        "salesExecutive" to setOf("leads", "customers", "quotations", "bookings", "events", "receipts"),
